// Cloudflare Pages Function: handles requests to "/" only (rhymegold.com/, which this Pages project serves).
//
// Since 2026-11-14 RhymeGold lives on lyricgenie.app: the home page 301s to the Rhyme Generator, keeping any
// lookup (rhymegold.com/?q=love -> lyricgenie.app/rhyme-generator/?q=love). Every other rhymegold.com path is
// redirected by public/_redirects (generated by tools/rhymes/build-word-pages.mjs). A Function, because "/" is
// routed here before _redirects is consulted.
export async function onRequest({ request }) {
  const from = new URL(request.url);
  return Response.redirect(`https://lyricgenie.app/rhyme-generator/${from.search}`, 301);
}
